-- Database: uang_pengiriman

BEGIN;

-- Table: app_menus
CREATE TABLE IF NOT EXISTS app_menus (
  id TEXT PRIMARY KEY,
  label TEXT NOT NULL,
  path TEXT NOT NULL,
  section TEXT NOT NULL,
  icon TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  read_permission TEXT NOT NULL,
  write_permission TEXT
);


-- Table: app_settings
CREATE TABLE IF NOT EXISTS app_settings (
  id SERIAL PRIMARY KEY,
  app_name VARCHAR NOT NULL DEFAULT 'Biaya Pengiriman'::character varying,
  app_subtitle VARCHAR NOT NULL DEFAULT 'Premium Logistics'::character varying,
  logo_base64 TEXT,
  favicon_base64 TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  finance_can_unlock_customer BOOLEAN NOT NULL DEFAULT false
);


-- Table: bbm_master
CREATE TABLE IF NOT EXISTS bbm_master (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  price NUMERIC(14,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Table: drivers
CREATE TABLE IF NOT EXISTS drivers (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  phone TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  bank_name TEXT,
  bank_account TEXT
);


-- Table: toll_golongan
CREATE TABLE IF NOT EXISTS toll_golongan (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  code TEXT NOT NULL UNIQUE,
  description TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Table: toll_sections
CREATE TABLE IF NOT EXISTS toll_sections (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  length_km NUMERIC(10,2) NOT NULL DEFAULT 1,
  gol23 NUMERIC(14,2) NOT NULL,
  gol45 NUMERIC(14,2) NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  network TEXT,
  origin_name TEXT,
  destination_name TEXT
);


-- Table: uang_mel_master
CREATE TABLE IF NOT EXISTS uang_mel_master (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  amount NUMERIC(14,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);


-- Table: users
CREATE TABLE IF NOT EXISTS users (
  id BIGSERIAL PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  full_name TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'marketing'::text,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Table: vehicle_brands
CREATE TABLE IF NOT EXISTS vehicle_brands (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- Table: warehouse_settings
CREATE TABLE IF NOT EXISTS warehouse_settings (
  id BIGINT PRIMARY KEY,
  name TEXT NOT NULL DEFAULT 'Gudang Utama'::text,
  address TEXT,
  city TEXT,
  latitude NUMERIC(10,7),
  longitude NUMERIC(10,7),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  kelurahan TEXT,
  kecamatan TEXT
);


-- Table: role_menu_access
CREATE TABLE IF NOT EXISTS role_menu_access (
  menu_id TEXT,
  role TEXT,
  access_level TEXT NOT NULL,
  PRIMARY KEY (menu_id, role),
  FOREIGN KEY (menu_id) REFERENCES app_menus(id) ON DELETE CASCADE,
  CHECK ((access_level = ANY (ARRAY['full'::text, 'read'::text, 'none'::text])))
);


-- Table: toll_gates
CREATE TABLE IF NOT EXISTS toll_gates (
  id BIGSERIAL PRIMARY KEY,
  section_id BIGINT NOT NULL,
  code TEXT NOT NULL,
  name TEXT NOT NULL,
  latitude NUMERIC(10,7),
  longitude NUMERIC(10,7),
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(section_id, code),
  FOREIGN KEY (section_id) REFERENCES toll_sections(id) ON DELETE CASCADE
);


-- Table: toll_section_rates
CREATE TABLE IF NOT EXISTS toll_section_rates (
  id BIGSERIAL PRIMARY KEY,
  section_id BIGINT NOT NULL,
  golongan_id BIGINT NOT NULL,
  rate NUMERIC(14,2) NOT NULL DEFAULT 0,
  UNIQUE(section_id, golongan_id),
  FOREIGN KEY (golongan_id) REFERENCES toll_golongan(id) ON DELETE CASCADE,
  FOREIGN KEY (section_id) REFERENCES toll_sections(id) ON DELETE CASCADE
);


-- Table: vehicle_types
CREATE TABLE IF NOT EXISTS vehicle_types (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  toll_golongan_id BIGINT,
  bbm_id BIGINT,
  km_per_liter NUMERIC(10,2),
  uang_mel_id INTEGER,
  FOREIGN KEY (bbm_id) REFERENCES bbm_master(id) ON DELETE SET NULL,
  FOREIGN KEY (toll_golongan_id) REFERENCES toll_golongan(id) ON DELETE SET NULL,
  FOREIGN KEY (uang_mel_id) REFERENCES uang_mel_master(id) ON DELETE SET NULL
);


-- Table: toll_gate_fares
CREATE TABLE IF NOT EXISTS toll_gate_fares (
  id BIGSERIAL PRIMARY KEY,
  entry_gate_id BIGINT NOT NULL,
  exit_gate_id BIGINT NOT NULL,
  golongan_id BIGINT NOT NULL,
  rate NUMERIC(14,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(entry_gate_id, exit_gate_id, golongan_id),
  FOREIGN KEY (entry_gate_id) REFERENCES toll_gates(id) ON DELETE CASCADE,
  FOREIGN KEY (exit_gate_id) REFERENCES toll_gates(id) ON DELETE CASCADE,
  FOREIGN KEY (golongan_id) REFERENCES toll_golongan(id) ON DELETE CASCADE
);


-- Table: customers
CREATE TABLE IF NOT EXISTS customers (
  id BIGSERIAL PRIMARY KEY,
  code TEXT UNIQUE,
  name TEXT NOT NULL,
  address TEXT,
  city TEXT,
  phone TEXT,
  email TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  vehicle_type_id BIGINT,
  uang_jalan NUMERIC(14,2) NOT NULL DEFAULT 0,
  latitude NUMERIC(10,7),
  longitude NUMERIC(10,7),
  kelurahan TEXT,
  kecamatan TEXT,
  force_toll BOOLEAN DEFAULT false,
  custom_toll_breakdown TEXT,
  is_locked_marketing BOOLEAN DEFAULT false,
  updated_at TIMESTAMPTZ,
  updated_by_id INTEGER,
  share_location VARCHAR,
  is_locked_finance BOOLEAN DEFAULT false,
  FOREIGN KEY (updated_by_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types(id) ON DELETE SET NULL
);


-- Table: vehicles
CREATE TABLE IF NOT EXISTS vehicles (
  id BIGSERIAL PRIMARY KEY,
  plate_number TEXT NOT NULL UNIQUE,
  brand_id BIGINT NOT NULL,
  type_id BIGINT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY (brand_id) REFERENCES vehicle_brands(id) ON UPDATE CASCADE,
  FOREIGN KEY (type_id) REFERENCES vehicle_types(id) ON UPDATE CASCADE
);


-- Table: cash_disbursements
CREATE TABLE IF NOT EXISTS cash_disbursements (
  id BIGSERIAL PRIMARY KEY,
  amount NUMERIC(14,2) NOT NULL,
  description TEXT,
  disbursed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  customer_id BIGINT,
  vehicle_type_id BIGINT,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types(id) ON DELETE SET NULL,
  CHECK ((amount > (0)::numeric))
);

-- Table: customer_vehicle_tariffs
CREATE TABLE IF NOT EXISTS customer_vehicle_tariffs (
  id BIGSERIAL PRIMARY KEY,
  customer_id BIGINT NOT NULL,
  vehicle_type_id BIGINT NOT NULL,
  uang_jalan NUMERIC(14,2) NOT NULL DEFAULT 0,
  bbm NUMERIC(14,2) NOT NULL DEFAULT 0,
  tol NUMERIC(14,2) NOT NULL DEFAULT 0,
  parkir NUMERIC(14,2) NOT NULL DEFAULT 0,
  lain_lain NUMERIC(14,2) NOT NULL DEFAULT 0,
  uang_mel NUMERIC(14,2) NOT NULL DEFAULT 0,
  UNIQUE(customer_id, vehicle_type_id),
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE,
  FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types(id) ON DELETE CASCADE
);


-- Table: delivery_routes
CREATE TABLE IF NOT EXISTS delivery_routes (
  id BIGSERIAL PRIMARY KEY,
  route_no TEXT NOT NULL UNIQUE,
  date DATE NOT NULL,
  vehicle_id BIGINT,
  driver_id BIGINT,
  remarks TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  vehicle_type_id BIGINT,
  ritpiase INTEGER NOT NULL DEFAULT 1,
  FOREIGN KEY (driver_id) REFERENCES drivers(id) ON UPDATE CASCADE,
  FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON UPDATE CASCADE,
  FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types(id) ON UPDATE CASCADE
);


-- Table: delivery_route_stops
CREATE TABLE IF NOT EXISTS delivery_route_stops (
  id BIGSERIAL PRIMARY KEY,
  route_id BIGINT NOT NULL,
  customer_id BIGINT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  description TEXT,
  entity_code VARCHAR(64),
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON UPDATE CASCADE,
  FOREIGN KEY (route_id) REFERENCES delivery_routes(id) ON DELETE CASCADE
);


-- Table: sales
CREATE TABLE IF NOT EXISTS sales (
  id BIGSERIAL PRIMARY KEY,
  sale_no TEXT NOT NULL UNIQUE,
  date DATE NOT NULL,
  vehicle_id BIGINT,
  driver_id BIGINT,
  remarks TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  extra_uang_jalan NUMERIC(14,2) NOT NULL DEFAULT 0,
  delivery_route_id BIGINT,
  finance_paid_at TIMESTAMPTZ,
  finance_paid_by BIGINT,
  FOREIGN KEY (delivery_route_id) REFERENCES delivery_routes(id) ON DELETE CASCADE,
  FOREIGN KEY (driver_id) REFERENCES drivers(id) ON UPDATE CASCADE,
  FOREIGN KEY (finance_paid_by) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON UPDATE CASCADE
);


-- Table: delivery_route_stop_lines
CREATE TABLE IF NOT EXISTS delivery_route_stop_lines (
  id BIGSERIAL PRIMARY KEY,
  stop_id BIGINT NOT NULL,
  item_name TEXT NOT NULL,
  quantity NUMERIC(12,3) NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  FOREIGN KEY (stop_id) REFERENCES delivery_route_stops(id) ON DELETE CASCADE
);


-- Table: sale_details
CREATE TABLE IF NOT EXISTS sale_details (
  id BIGSERIAL PRIMARY KEY,
  sale_id BIGINT NOT NULL,
  customer_id BIGINT NOT NULL,
  amount NUMERIC(14,2) NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  vehicle_type_id BIGINT,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON UPDATE CASCADE,
  FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE CASCADE,
  FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types(id) ON UPDATE CASCADE
);


COMMIT;